// Chatbot RH - Holerites via WhatsApp | Autor: César Barth · 2026
// Extrai da mensagem da Meta só o que o robô precisa, já padronizado.
const body = $json.body || {};
const value = body.entry?.[0]?.changes?.[0]?.value || {};
const msg = value.messages?.[0] || {};
const contato = value.contacts?.[0] || {};

// Telefone: só números. No Brasil o WhatsApp às vezes manda sem o 9º dígito
// (55 + DDD + 8 dígitos = 12 dígitos). Recolocamos o 9 para padronizar.
let tel = String(msg.from || '').replace(/\D/g, '');
if (tel.startsWith('55') && tel.length === 12) {
  tel = tel.slice(0, 4) + '9' + tel.slice(4);
}

// Texto digitado ou ID do botão clicado
let texto = '';
if (msg.type === 'text') texto = msg.text?.body || '';
else if (msg.type === 'interactive') texto = msg.interactive?.button_reply?.id || msg.interactive?.list_reply?.id || '';
else if (msg.type === 'button') texto = msg.button?.payload || msg.button?.text || '';
texto = String(texto).trim();

// Possível confirmação de CPF: aceita os 5 primeiros dígitos ou o CPF inteiro (11 dígitos)
const digitos = texto.replace(/\D/g, '');
let cpf5 = '';
if (digitos.length === 5) cpf5 = digitos;
else if (digitos.length === 11) cpf5 = digitos.slice(0, 5);

return {
  json: {
    telefone: tel,
    ddd: tel.startsWith('55') ? tel.slice(2, 4) : tel.slice(0, 2),
    final8: tel.slice(-8),
    nome_perfil: contato.profile?.name || '',
    tipo_msg: msg.type || 'desconhecido',
    mensagem: texto,
    cpf5: cpf5,
    wamid: msg.id || '',
    timestamp: Number(msg.timestamp || 0),
    phone_number_id: value.metadata?.phone_number_id || ''
  }
};

// Chatbot RH - Holerites via WhatsApp | Autor: César Barth · 2026
// =====================================================================
// CÉREBRO DO ROBÔ: olha o estado da conversa + a mensagem recebida e
// decide o que responder e qual será o próximo estado.
// Ajuste os textos e os tempos aqui mesmo, se quiser.
// =====================================================================
const EMPRESA = 'Sua Empresa'; // nome que aparece nas mensagens do bot
const RH_WHATSAPP = '';            // WhatsApp do RH com DDI e DDD, só números (ex.: 5555999998888). Vazio = mensagem genérica
const MAX_TENTATIVAS = 3;          // tentativas de CPF antes de bloquear
const BLOQUEIO_MIN = 30;           // minutos de bloqueio após errar o CPF

const ctx = $json;                                   // resultado do "Buscar Contexto"
const ent = $('Normalizar Entrada').first().json;    // mensagem padronizada

const msg = (ent.mensagem || '').toLowerCase();
const funcionario = !!ctx.id_colaborador && ctx.colaborador_ativo === true;
const nomeCompleto = funcionario ? (ctx.nome_colaborador || '') : (ent.nome_perfil || '');
const primeiro = nomeCompleto.trim().split(' ')[0] || '';
const primeiroNome = primeiro ? primeiro.charAt(0).toUpperCase() + primeiro.slice(1).toLowerCase() : '';  // CESAR -> Cesar

// ---------- estado atual (com expirações) ----------
let estado = ctx.estado || 'INICIO';
if (estado === 'ATENDIMENTO_HUMANO') estado = 'INICIO';   // modo antigo: o bot não fica mais em silêncio
if (estado === 'BLOQUEADO' && !ctx.bloqueado) estado = 'INICIO';
if (ctx.sessao_expirada && estado !== 'BLOQUEADO') estado = 'INICIO';
const bloqueadoAgora = estado === 'BLOQUEADO';

// ---------- resultado padrão ----------
const r = {
  acao: 'enviar',              // enviar | buscar_folha | silencio
  telefone_envio: ent.telefone,
  id_colaborador: ctx.id_colaborador || 0,
  estado_anterior: ctx.estado || 'INICIO',
  novo_estado: estado,
  // As tentativas de CPF só zeram quando o CPF confere, no bloqueio ou após 30 min sem conversa.
  // Assim "menu" ou "encerrar" não dão tentativas extras.
  tentativas: ctx.sessao_expirada ? 0 : (ctx.tentativas_cpf || 0),
  bloqueio_min: 0,
  atendimento_min: 0,
  evento: '',
  detalhe: '',
  tipo_busca: '',
  mes_ref: '1900-01-01',
  wamid: ent.wamid,
  payload: null
};

// ---------- montadores de mensagem (formato da Meta) ----------
const RODAPE_SAIR = 'Para sair a qualquer momento, digite encerrar';
const texto = (t) => ({
  messaging_product: 'whatsapp', to: ent.telefone, type: 'text', text: { body: t }
});
const botoes = (t, lista) => {
  const temEncerrar = lista.some(([id]) => id === 'encerrar');
  const interactive = {
    type: 'button',
    body: { text: t },
    action: { buttons: lista.map(([id, title]) => ({ type: 'reply', reply: { id, title } })) }
  };
  if (!temEncerrar) interactive.footer = { text: RODAPE_SAIR };  // sem botão Encerrar, avisa no rodapé
  return { messaging_product: 'whatsapp', to: ent.telefone, type: 'interactive', interactive };
};

// Títulos de botão: no máximo 20 caracteres e no máximo 3 botões (limites da Meta)
const B_ENCERRAR = ['encerrar', 'Encerrar'];
const B_MENU     = ['menu', 'Menu inicial'];
const B_RH       = ['rh', 'Falar com o RH'];
const BOT_MENU_FUNC = [['1', 'Solicitar holerite'], B_RH, B_ENCERRAR];
const BOT_MENU_EXT  = [B_RH, B_ENCERRAR];
const BOT_RH_SAIR   = [B_RH, B_ENCERRAR];
const BOT_VOLTAR    = [B_MENU, B_ENCERRAR];
const BOT_PERIODOS  = [['1', 'Último holerite'], ['2', 'Últimos 3'], ['3', 'Escolher o mês']];
const BOT_POS       = [['seguir', 'Seguir atendimento'], B_MENU, B_ENCERRAR];
const TIPO_BOTAO = { ULTIMA: '1', ULTIMAS_3: '2', MES: '3' };

const CMD_MENU = ['menu', '0', 'voltar', 'inicio', 'início',
                  'oi', 'ola', 'olá', 'bom dia', 'boa tarde', 'boa noite'];
const CMD_ENCERRAR = ['encerrar', 'sair', 'cancelar', 'tchau', 'obrigado', 'obrigada'];
const pediuRH = msg === 'rh' || msg.includes('falar com');

// ---------- ações ----------
function menu(prefixo = '') {
  r.novo_estado = 'MENU';
  const saudacao = primeiroNome ? `Olá, ${primeiroNome}!` : 'Olá!';
  if (prefixo) {
    // Resposta curta quando a pessoa digitou algo fora das opções
    r.payload = funcionario
      ? botoes(`${prefixo}Escolha uma das opções abaixo:`, BOT_MENU_FUNC)
      : botoes(`${prefixo}Para falar com a equipe do RH da ${EMPRESA}, toque no botão abaixo.`, BOT_MENU_EXT);
  } else if (funcionario) {
    r.payload = botoes(`${saudacao} Sou o assistente virtual do RH da ${EMPRESA}. Como posso ajudar?`, BOT_MENU_FUNC);
  } else {
    r.payload = botoes(`${saudacao} Sou o assistente virtual do RH da ${EMPRESA}.\n\nNão encontrei este número no cadastro de colaboradores. Para qualquer assunto, toque no botão abaixo e fale com a nossa equipe do RH.`, BOT_MENU_EXT);
  }
}

// O bot não fica em silêncio: indica o contato do RH e continua disponível
function encaminharRH() {
  r.novo_estado = 'MENU';
  r.evento = 'ENCAMINHADO_RH';
  const contato = RH_WHATSAPP
    ? `Toque no link para falar com a equipe do RH da ${EMPRESA}:\nhttps://wa.me/${RH_WHATSAPP}`
    : `Procure a equipe do RH da ${EMPRESA} pelo WhatsApp ou telefone do setor.`;
  r.payload = botoes(`👤 ${contato}\n\nSe precisar de algo mais por aqui, escolha uma opção:`, BOT_VOLTAR);
}

function encerrar() {
  r.novo_estado = 'INICIO';
  r.payload = texto('👋 Atendimento encerrado. Obrigado! Quando precisar, é só mandar uma mensagem por aqui.');
}

// Mostra as opções de período que a pessoa ainda não usou + "Menu inicial"
function seguir(ultimoTipo) {
  const usado = TIPO_BOTAO[ultimoTipo];
  const restantes = BOT_PERIODOS.filter(([id]) => id !== usado).slice(0, 2);
  r.novo_estado = 'AGUARDANDO_PERIODO';
  r.payload = botoes('Qual outro holerite você precisa?', [...restantes, B_MENU]);
}

function pedirCPF() {
  r.novo_estado = 'AGUARDANDO_CPF';
  r.payload = botoes('🔐 Para sua segurança, digite os *5 primeiros dígitos do seu CPF*.\n' +
    '(Exemplo: se o CPF é 123.456.789-01, digite 12345)', BOT_RH_SAIR);
}

function buscar(tipo, mes) {
  r.acao = 'buscar_folha';
  r.tipo_busca = tipo;
  if (mes) r.mes_ref = mes;
  r.novo_estado = 'POS_ENTREGA:' + tipo;  // depois da entrega: Seguir / Menu inicial / Encerrar
  r.evento = 'PEDIDO_HOLERITE';
  r.detalhe = tipo + (mes ? ' ' + mes.slice(5, 7) + '/' + mes.slice(0, 4) : '');
}

// Aceita 05/2026, 5/2026, 05-2026, 05.26 ...
function lerMes(t) {
  const m = String(t).trim().match(/^(\d{1,2})\s*[\/\-.]\s*(\d{2}|\d{4})$/);
  if (!m) return null;
  const mes = parseInt(m[1], 10);
  let ano = parseInt(m[2], 10);
  if (ano < 100) ano += 2000;
  if (mes < 1 || mes > 12 || ano < 2000 || ano > 2100) return null;
  return `${ano}-${String(mes).padStart(2, '0')}-01`;
}

// ---------- regras ----------
const tiposEntendidos = ['text', 'interactive', 'button'];

const idadeMin = ent.timestamp ? (Date.now() / 1000 - ent.timestamp) / 60 : 0;

if (ctx.duplicada) {
  // A Meta reenviou a mesma mensagem: ignora para não responder em dobro
  r.acao = 'silencio';

} else if (idadeMin > 10) {
  // Mensagem atrasada: a Meta reenvia as mensagens que não conseguiu entregar
  // enquanto o servidor estava fora do ar. Não responde, só registra.
  r.acao = 'silencio';
  r.evento = 'MSG_ATRASADA';
  r.detalhe = `${Math.round(idadeMin)} min de atraso`;

} else if (ent.tipo_msg === 'reaction') {
  r.acao = 'silencio';

} else if (!tiposEntendidos.includes(ent.tipo_msg)) {
  r.payload = botoes('Desculpe, por aqui eu só consigo entender mensagens de texto e os botões. 🙂', BOT_VOLTAR);

} else if (CMD_ENCERRAR.includes(msg)) {
  // Encerrar funciona em qualquer etapa
  encerrar();

} else if (pediuRH || (estado === 'MENU' && msg === '2')) {
  // Falar com o RH funciona em qualquer etapa (inclusive bloqueado)
  encaminharRH();

} else if (estado === 'BLOQUEADO') {
  r.payload = botoes('🔒 Por segurança, a consulta de documentos deste número está bloqueada temporariamente. ' +
    'Tente novamente mais tarde ou fale com o RH.', BOT_RH_SAIR);

} else if (CMD_MENU.includes(msg) || estado === 'INICIO') {
  menu();

} else if ((['AGUARDANDO_CPF', 'AGUARDANDO_PERIODO', 'AGUARDANDO_MES'].includes(estado) || estado.startsWith('POS_ENTREGA')) && !funcionario) {
  // Segurança: se o cadastro deixou de valer no meio da conversa, volta ao início
  menu();

} else if (estado === 'MENU') {
  if (msg === '1' || msg.includes('holerite') || msg.includes('contracheque')) {
    if (funcionario) {
      pedirCPF();
    } else {
      r.novo_estado = 'MENU';
      r.evento = 'NAO_CADASTRADO';
      r.payload = botoes('Não encontrei este número no cadastro de colaboradores ativos, por isso não consigo enviar documentos. ' +
        'Se você é colaborador, fale com o RH para atualizar seu telefone.', BOT_MENU_EXT);
    }
  } else {
    menu('Não entendi sua resposta. ');
  }

} else if (estado === 'AGUARDANDO_CPF') {
  if (!ent.cpf5) {
    r.payload = botoes('Por favor, digite apenas os *5 primeiros dígitos* do seu CPF (somente números).', BOT_RH_SAIR);
  } else if (ctx.cpf_confere === true) {
    r.novo_estado = 'AGUARDANDO_PERIODO';
    r.tentativas = 0;
    r.evento = 'CPF_CONFIRMADO';
    r.payload = botoes('✅ Identidade confirmada! Qual holerite você precisa?', BOT_PERIODOS);
  } else {
    const t = r.tentativas + 1;
    if (t >= MAX_TENTATIVAS) {
      r.novo_estado = 'BLOQUEADO';
      r.tentativas = 0;
      r.bloqueio_min = BLOQUEIO_MIN;
      r.evento = 'BLOQUEIO_CPF';
      r.detalhe = `${t} tentativas incorretas`;
      r.payload = botoes(`🔒 Os dígitos não conferem. Por segurança, nenhum documento foi enviado e a consulta foi bloqueada por ${BLOQUEIO_MIN} minutos.\n\n` +
        'Se precisar de ajuda, fale com o RH.', BOT_RH_SAIR);
    } else {
      r.tentativas = t;
      r.evento = 'CPF_INCORRETO';
      r.detalhe = `tentativa ${t}`;
      r.payload = botoes(`❌ Os dígitos não conferem com o cadastro. Você ainda tem ${MAX_TENTATIVAS - t} tentativa(s).\n` +
        'Digite novamente os 5 primeiros dígitos do seu CPF, ou fale com o RH.', BOT_RH_SAIR);
    }
  }

} else if (estado.startsWith('POS_ENTREGA') && msg === 'seguir') {
  seguir(estado.split(':')[1]);

} else if (estado.startsWith('POS_ENTREGA') && !['1', '2', '3'].includes(msg) && !lerMes(ent.mensagem)) {
  r.payload = botoes('Não entendi. Posso ajudar em algo mais?', BOT_POS);

} else if (estado === 'AGUARDANDO_PERIODO' || estado === 'AGUARDANDO_MES' || estado.startsWith('POS_ENTREGA')) {
  if (estado.startsWith('POS_ENTREGA')) estado = 'AGUARDANDO_PERIODO';
  const mes = lerMes(ent.mensagem);
  if (estado === 'AGUARDANDO_PERIODO' && msg === '1') {
    buscar('ULTIMA');
  } else if (estado === 'AGUARDANDO_PERIODO' && msg === '2') {
    buscar('ULTIMAS_3');
  } else if (estado === 'AGUARDANDO_PERIODO' && msg === '3') {
    r.novo_estado = 'AGUARDANDO_MES';
    r.payload = botoes('📅 Digite o mês e o ano do holerite no formato *MM/AAAA*.\nExemplo: 05/2026', BOT_VOLTAR);
  } else if (mes) {
    buscar('MES', mes);
  } else if (estado === 'AGUARDANDO_MES') {
    r.payload = botoes('Não consegui entender a data. Use o formato *MM/AAAA* (exemplo: 05/2026).', BOT_VOLTAR);
  } else {
    r.payload = botoes('Não entendi. Escolha uma das opções abaixo:', BOT_PERIODOS);
  }

} else {
  // Qualquer estado desconhecido volta ao menu
  menu();
}

// Segurança: enquanto o bloqueio estiver valendo, nada (encerrar, menu, RH) tira o número do bloqueio
if (bloqueadoAgora) {
  r.novo_estado = 'BLOQUEADO';
  if (r.acao === 'buscar_folha') { r.acao = 'enviar'; r.payload = null; }
}

// Garantia: nunca tentar enviar mensagem vazia
if (r.acao === 'enviar' && !r.payload) r.acao = 'silencio';

return { json: r };

// Chatbot RH - Holerites via WhatsApp | Autor: César Barth · 2026
const d = $('Decidir Ação').first().json;
const desc = d.tipo_busca === 'MES'
  ? `de ${d.mes_ref.slice(5, 7)}/${d.mes_ref.slice(0, 4)}`
  : 'disponível';
return [{
  json: {
    payload: {
      messaging_product: 'whatsapp', to: d.telefone_envio, type: 'interactive',
      interactive: {
        type: 'button',
        body: { text: `📭 Não encontrei holerite ${desc} no sistema.\nSe achar que é um erro, fale com o RH.\n\nPosso ajudar em algo mais?` },
        action: { buttons: [
          { type: 'reply', reply: { id: 'seguir', title: 'Seguir atendimento' } },
          { type: 'reply', reply: { id: 'menu', title: 'Menu inicial' } },
          { type: 'reply', reply: { id: 'encerrar', title: 'Encerrar' } }
        ] }
      }
    }
  }
}];

// Chatbot RH - Holerites via WhatsApp | Autor: César Barth · 2026
const d = $('Decidir Ação').first().json;
return [{
  json: {
    payload: {
      messaging_product: 'whatsapp', to: d.telefone_envio, type: 'interactive',
      interactive: {
        type: 'button',
        body: { text: '⚠️ Encontrei o seu holerite no sistema, mas tive um problema para abrir o arquivo. Tente outro período ou fale com o RH pelo menu inicial.\n\nPosso ajudar em algo mais?' },
        action: { buttons: [
          { type: 'reply', reply: { id: 'seguir', title: 'Seguir atendimento' } },
          { type: 'reply', reply: { id: 'menu', title: 'Menu inicial' } },
          { type: 'reply', reply: { id: 'encerrar', title: 'Encerrar' } }
        ] }
      }
    }
  }
}];

// Chatbot RH - Holerites via WhatsApp | Autor: César Barth · 2026
// Monta a mensagem de documento com o ID que a Meta devolveu no upload
const d = $('Decidir Ação').first().json;
const f = $('Buscar Folhas').item.json;
const mes = f.mes_label || '';
const tipo = f.tipo_folha || 'Mensal';
return {
  json: {
    payload: {
      messaging_product: 'whatsapp', to: d.telefone_envio, type: 'document',
      document: { id: $json.id, filename: `Holerite_${tipo}_${mes.replace('/', '-')}.pdf`, caption: `📄 Holerite ${tipo} ${mes}` }
    }
  }
};

// Chatbot RH - Holerites via WhatsApp | Autor: César Barth · 2026
// Uma única mensagem final, independente de quantos PDFs foram enviados
const d = $('Decidir Ação').first().json;
const n = $input.all().length;
return [{
  json: {
    payload: {
      messaging_product: 'whatsapp', to: d.telefone_envio, type: 'interactive',
      interactive: {
        type: 'button',
        body: { text: `✅ Pronto! Enviei ${n} holerite(s).\n\nPosso ajudar em algo mais?` },
        action: { buttons: [
          { type: 'reply', reply: { id: 'seguir', title: 'Seguir atendimento' } },
          { type: 'reply', reply: { id: 'menu', title: 'Menu inicial' } },
          { type: 'reply', reply: { id: 'encerrar', title: 'Encerrar' } }
        ] }
      }
    }
  }
}];
